h, w = len(grid), len(grid[0])

def find_all_partial_rectangles():
    visited = [[False]*w for _ in range(h)]

    def bfs(start_r, start_c):
        comp = []
        queue = [(start_r, start_c)]
        visited[start_r][start_c] = True

        while queue:
            r, c = queue.pop(0)
            comp.append((r, c))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    if not visited[nr][nc] and grid[nr][nc] == grid[r][c]:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
        return comp

    colors_seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                colors_seen.add(grid[r][c])

    partials = []

