        for r in range(h):
            for c in range(w):
                if grid[r][c] == color and not visited[r][c]:
                    comp = bfs(r, c)
                    rr, cc = zip(*comp)
                    top, left = min(rr), min(cc)
                    bot, right = max(rr), max(cc)

                    bbox_area = (bot-top+1) * (right-left+1)
                    cell_count = len(comp)
                    ratio = cell_count / bbox_area

                    if ratio >= 0.75:
                        missing_cells = []
                        for nr in range(top, bot+1):
                            for nc in range(left, right+1):
                                if (nr, nc) not in comp:
                                    missing_cells.append((nr, nc))

                        partals.append({
                            'color': color,
                            'cells': comp,
                            'bbox': (top, left, bot, right),
                            'missing': missing_cells,
                            'ratio': ratio
                        })

    return partials

